import { NextResponse, type NextRequest } from 'next/server';

import { requireValidPhone } from '@/lib/phoneUtils';
import { isTailorLocale, type TailorSegment } from '@/lib/tailor-now';
import { createTailorPlan, hashIp, parseTailorAnswers, TailorError } from '@/lib/tailor-now-server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/** POST /api/tailor-now — create a plan (Day 1 is generated by the plan page right after). */
export async function POST(request: NextRequest) {
  let body: Record<string, unknown> = {};
  try {
    body = (await request.json()) as Record<string, unknown>;
  } catch {
    return NextResponse.json({ ok: false, error: 'invalid_json' }, { status: 400 });
  }

  // Honeypot: real visitors never fill this hidden field.
  if (String(body.website ?? '').trim()) {
    return NextResponse.json({ ok: false, error: 'rejected' }, { status: 400 });
  }

  const fullName = String(body.fullName ?? '').trim().slice(0, 120);
  if (fullName.length < 2) return NextResponse.json({ ok: false, error: 'name_required' }, { status: 400 });

  const phone = requireValidPhone(String(body.phoneWa ?? ''));
  if (!phone.isValid) return NextResponse.json({ ok: false, error: 'phone_invalid' }, { status: 400 });

  const email = String(body.email ?? '').trim().slice(0, 160);
  if (email && !EMAIL_RE.test(email)) return NextResponse.json({ ok: false, error: 'email_invalid' }, { status: 400 });

  const startRaw = String(body.startDate ?? '').trim();
  const startDate = /^\d{4}-\d{2}-\d{2}$/.test(startRaw) ? startRaw : null;

  const segments: TailorSegment[] = (Array.isArray(body.segments) ? body.segments : []).map((s) => {
    const r = (s ?? {}) as Record<string, unknown>;
    return { city: String(r.city ?? '').trim(), days: Math.trunc(Number(r.days) || 0) };
  });

  try {
    const { token } = await createTailorPlan(
      {
        locale: isTailorLocale(body.locale) ? body.locale : 'ar',
        fullName,
        phoneWa: phone.formattedPhone,
        email,
        countryId: String(body.countryId ?? '').trim(),
        segments,
        startDate,
        answers: parseTailorAnswers(body.answers),
      },
      {
        ipHash: hashIp(request.headers.get('x-forwarded-for') ?? request.headers.get('x-real-ip')),
        origin: request.nextUrl.origin,
      },
    );
    return NextResponse.json({ ok: true, token });
  } catch (err) {
    if (err instanceof TailorError) {
      return NextResponse.json({ ok: false, error: err.code }, { status: err.status });
    }
    console.error('[api/tailor-now] create failed:', err);
    return NextResponse.json({ ok: false, error: 'server_error' }, { status: 500 });
  }
}
